$('#cloudRegister').onclick=async()=>{const email=$('#cloudEmail').value.trim(),password=$('#cloudPassword').value;if(!email||password.length<6){msg('⚠ Bitte gültige E-Mail und mindestens 6 Zeichen Passwort eingeben.');return}const {data,error}=await client.auth.signUp({email,password,options:{emailRedirectTo:new URL('index.html',location.href).href}});msg(error?'⚠ '+error.message:(data.session?'✓ Konto erstellt und angemeldet.':'✓ Konto erstellt. Bitte E-Mail bestätigen.'))};
$('#cloudForgot').onclick=async()=>{const email=$('#cloudEmail').value.trim(),btn=$('#cloudForgot');if(!email){msg('⚠ Bitte zuerst deine E-Mail-Adresse eintragen.');return}btn.disabled=true;const {error}=await client.auth.resetPasswordForEmail(email,{redirectTo:new URL('index.html',location.href).href});if(error){const t=String(error.message||'').toLowerCase();msg(t.includes('rate limit')?'⚠ Zu viele E-Mail-Anfragen. Bitte einige Minuten warten und dann erneut versuchen.':'⚠ '+error.message);setTimeout(()=>btn.disabled=false,30000);return}msg('✓ Reset-Link wurde angefordert. Bitte E-Mail prüfen.');setTimeout(()=>btn.disabled=false,30000)};
